#!run
import {Tonyu} from "tonyu2-runtime";
import {t} from "@hoge1e3/dom";
//import "../js/concat.js";
import * as pNode from "petit-node";
import {dir} from "@acepad/here";
export async function main(prjPath){
  const e=document.body;
  const rect=e.getBoundingClientRect();
  const cv=t.canvas();
  cv.setAttribute("width",rect.width);
  cv.setAttribute("height",rect.height);
  e.appendChild(cv);
  let g=Tonyu.globals;
  let prjDir=pNode.file(prjPath);//dir(import.meta.url).up();
  console.log("prjDir",prjDir);
  await pNode.importModule(prjDir);
  g.$mainCanvas=$(cv);
  //g.$shell=this;
  g.$pNode=pNode;
  globalThis.UIDiag={};
  g.$currentProject={
      getResource(){
        const r={
          images:[],sounds:[]
        };
        //console.log("getResource",r);
        return r;
      },
      getOptions:()=>({
          run: {
              mainClass: "user.Main",
          },
      }),
      loadPlugins:(s)=>s(),
      requestPlugin:(s)=>console.log("Plugin", s),
      getDir() {
        return prjDir;//sh.resolve(".");
      }
  };
  globalThis.FS=pNode.FS;
  globalThis.ImageList={
      load:(_,succ)=>succ({names:[]})
  };
  globalThis.T2MediaLib=class {
    activate(){
    }
  };
  Tonyu.run("kernel.Boot");
  return ;
}
globalThis.main=main;